{{ config(materialized='semantic_view', schema='SEMANTIC') }}

TABLES(
    people AS {{ ref('fct_mhsds_person_summary') }}
        PRIMARY KEY (person_id) COMMENT = 'One identifiable MHSDS person, current evidence summary',
    referrals AS {{ ref('fct_mhsds_referral_summary') }}
        PRIMARY KEY (source_record_id) COMMENT = 'One recorded referral with access measures',
    contacts AS {{ ref('fct_mhsds_care_contact') }}
        PRIMARY KEY (source_record_id) COMMENT = 'One latest referral/contact pair, all attendance states',
    spells AS {{ ref('fct_mhsds_hospital_provider_spell') }}
        PRIMARY KEY (source_record_id) COMMENT = 'One recorded provider spell, before occupancy inference',
    occupancy AS {{ ref('fct_mhsds_inpatient_occupancy') }}
        PRIMARY KEY (occupancy_interval_id) COMMENT = 'One retained inferred occupancy interval',
    diagnoses AS {{ ref('fct_mhsds_diagnosis') }}
        PRIMARY KEY (diagnosis_record_id) COMMENT = 'One retained diagnosis evidence item',
    assessments AS {{ ref('fct_mhsds_assessment_observation') }}
        PRIMARY KEY (assessment_observation_id) COMMENT = 'One accepted assessment question, dimension or score occurrence',
    legal_status AS {{ ref('fct_mhsds_mental_health_act_period') }}
        PRIMARY KEY (mental_health_act_period_id) COMMENT = 'One recorded legal-status period',
    submissions AS {{ ref('dq_mhsds_provider_submission') }}
        PRIMARY KEY (provider_organisation_code, reporting_period_end_date) COMMENT = 'One provider and accepted reporting period',
    demographics AS {{ ref('dim_mhsds_person_provider_period') }}
        PRIMARY KEY (person_provider_period_id) COMMENT = 'Reporting entity dim_mhsds_person_provider_period; see model description for grain and population',
    referral_periods AS {{ ref('fct_mhsds_referral_period') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Reporting entity fct_mhsds_referral_period; see model description for grain and population',
    caseload_referrals AS {{ ref('fct_mhsds_current_caseload_referral') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Reporting entity fct_mhsds_current_caseload_referral; see model description for grain and population',
    caseload_people AS {{ ref('fct_mhsds_current_caseload_person') }}
        PRIMARY KEY (caseload_person_provider_id) COMMENT = 'Reporting entity fct_mhsds_current_caseload_person; see model description for grain and population',
    rtt AS {{ ref('fct_mhsds_referral_to_treatment_period') }}
        PRIMARY KEY (referral_to_treatment_period_id) COMMENT = 'Reporting entity fct_mhsds_referral_to_treatment_period; see model description for grain and population',
    indirect_activity AS {{ ref('fct_mhsds_indirect_activity') }}
        PRIMARY KEY (indirect_activity_id) COMMENT = 'Reporting entity fct_mhsds_indirect_activity; see model description for grain and population',
    group_sessions AS {{ ref('fct_mhsds_group_session') }}
        PRIMARY KEY (group_session_id) COMMENT = 'Reporting entity fct_mhsds_group_session; see model description for grain and population',
    group_therapy AS {{ ref('fct_mhsds_group_therapy_contact') }}
        PRIMARY KEY (group_therapy_contact_id) COMMENT = 'Reporting entity fct_mhsds_group_therapy_contact; see model description for grain and population',
    drop_ins AS {{ ref('fct_mhsds_drop_in_contact') }}
        PRIMARY KEY (drop_in_contact_id) COMMENT = 'Reporting entity fct_mhsds_drop_in_contact; see model description for grain and population',
    accommodation AS {{ ref('fct_mhsds_accommodation_observation') }}
        PRIMARY KEY (accommodation_observation_id) COMMENT = 'Reporting entity fct_mhsds_accommodation_observation; see model description for grain and population',
    employment AS {{ ref('fct_mhsds_employment_observation') }}
        PRIMARY KEY (employment_observation_id) COMMENT = 'Reporting entity fct_mhsds_employment_observation; see model description for grain and population',
    disability AS {{ ref('fct_mhsds_disability_observation') }}
        PRIMARY KEY (disability_observation_id) COMMENT = 'Reporting entity fct_mhsds_disability_observation; see model description for grain and population',
    social_circumstances AS {{ ref('fct_mhsds_social_circumstance_observation') }}
        PRIMARY KEY (social_circumstance_observation_id) COMMENT = 'Reporting entity fct_mhsds_social_circumstance_observation; see model description for grain and population',
    care_plans AS {{ ref('fct_mhsds_care_plan_period') }}
        PRIMARY KEY (care_plan_period_id) COMMENT = 'Reporting entity fct_mhsds_care_plan_period; see model description for grain and population',
    care_plan_agreements AS {{ ref('fct_mhsds_care_plan_agreement') }}
        PRIMARY KEY (care_plan_agreement_id) COMMENT = 'Reporting entity fct_mhsds_care_plan_agreement; see model description for grain and population',
    complaints AS {{ ref('fct_mhsds_presenting_complaint') }}
        PRIMARY KEY (presenting_complaint_id) COMMENT = 'Reporting entity fct_mhsds_presenting_complaint; see model description for grain and population',
    assessment_instances AS {{ ref('fct_mhsds_assessment_instance') }}
        PRIMARY KEY (assessment_instance_id) COMMENT = 'Reporting entity fct_mhsds_assessment_instance; see model description for grain and population',
    score_changes AS {{ ref('fct_mhsds_assessment_score_change') }}
        PRIMARY KEY (assessment_score_change_id) COMMENT = 'Reporting entity fct_mhsds_assessment_score_change; see model description for grain and population',
    ctos AS {{ ref('fct_mhsds_community_treatment_order') }}
        PRIMARY KEY (community_treatment_order_id) COMMENT = 'Reporting entity fct_mhsds_community_treatment_order; see model description for grain and population',
    recalls AS {{ ref('fct_mhsds_community_treatment_order_recall') }}
        PRIMARY KEY (community_treatment_order_recall_id) COMMENT = 'Reporting entity fct_mhsds_community_treatment_order_recall; see model description for grain and population',
    restrictive_incidents AS {{ ref('fct_mhsds_restrictive_intervention_incident') }}
        PRIMARY KEY (restrictive_intervention_incident_id) COMMENT = 'Reporting entity fct_mhsds_restrictive_intervention_incident; see model description for grain and population',
    restrictive_types AS {{ ref('fct_mhsds_restrictive_intervention_type') }}
        PRIMARY KEY (restrictive_intervention_type_id) COMMENT = 'Reporting entity fct_mhsds_restrictive_intervention_type; see model description for grain and population',
    home_leave AS {{ ref('fct_mhsds_home_leave') }}
        PRIMARY KEY (home_leave_id) COMMENT = 'Reporting entity fct_mhsds_home_leave; see model description for grain and population',
    leave AS {{ ref('fct_mhsds_leave_of_absence') }}
        PRIMARY KEY (leave_of_absence_id) COMMENT = 'Reporting entity fct_mhsds_leave_of_absence; see model description for grain and population',
    awol AS {{ ref('fct_mhsds_absence_without_leave') }}
        PRIMARY KEY (absence_without_leave_id) COMMENT = 'Reporting entity fct_mhsds_absence_without_leave; see model description for grain and population',
    spell_commissioners AS {{ ref('fct_mhsds_spell_commissioner_period') }}
        PRIMARY KEY (spell_commissioner_period_id) COMMENT = 'Reporting entity fct_mhsds_spell_commissioner_period; see model description for grain and population',
    readiness AS {{ ref('fct_mhsds_discharge_readiness_period') }}
        PRIMARY KEY (discharge_readiness_period_id) COMMENT = 'Reporting entity fct_mhsds_discharge_readiness_period; see model description for grain and population',
    ward_capacity AS {{ ref('fct_mhsds_ward_capacity_period') }}
        PRIMARY KEY (ward_capacity_period_id) COMMENT = 'Reporting entity fct_mhsds_ward_capacity_period; see model description for grain and population',
    latest_provider_caseload AS {{ ref('fct_mhsds_latest_provider_caseload_referral') }}
        PRIMARY KEY (referral_period_id) COMMENT = 'Latest reported open referrals per provider, including stale periods'
)

